#!/usr/bin/env node
'use strict';

// Verifies squad-doctor against a temporary config dir and a mock model server.
const fs = require('fs');
const http = require('http');
const os = require('os');
const path = require('path');
const { spawn, spawnSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const DOCTOR = path.join(ROOT, 'payload', 'mcp', 'doctor.js');
const SYNC = path.join(ROOT, 'payload', 'mcp', 'sync-team.js');
const REGISTER = path.join(ROOT, 'payload', 'mcp', 'register-settings.js');
const MARKER =
  '<!-- Generated by muse-squad sync-team.js; edit muse-squad.toml and re-run the installer. -->';
const SECRET = 'doctor-secret-do-not-leak';

function assert(condition, message) {
  if (!condition) throw new Error(`assertion failed: ${message}`);
}

function expectContains(text, needle, label) {
  assert(text.includes(needle), `${label} contains ${JSON.stringify(needle)}`);
}

function baseEnv(overrides = {}) {
  const env = { ...process.env };
  delete env.MUSE_CONFIG_DIR;
  delete env.MUSE_SQUAD_CONFIG_FILE;
  return { ...env, ...overrides };
}

function runSync(script, args, env = baseEnv()) {
  return spawnSync(process.execPath, [script, ...args], { encoding: 'utf8', env });
}

function doctor(args, envOverrides = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [DOCTOR, ...args], { encoding: 'utf8', env: baseEnv(envOverrides) });
    let stdout = '';
    let stderr = '';
    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');
    child.stdout.on('data', (chunk) => { stdout += chunk; });
    child.stderr.on('data', (chunk) => { stderr += chunk; });
    child.on('error', reject);
    child.on('close', (status) => resolve({ status, stdout, stderr }));
  });
}

async function expectDoctor(args, { status = 0, contains = [], absent = [], env = {} } = {}) {
  const result = await doctor(args, env);
  const output = `${result.stdout}${result.stderr}`;
  assert(result.status === status, `doctor exited ${result.status} (expected ${status}): ${output}`);
  assert(!output.includes(SECRET), 'doctor output must not leak api keys');
  for (const needle of contains) expectContains(output, needle, 'doctor output');
  for (const needle of absent) assert(!output.includes(needle), `doctor output must not contain ${JSON.stringify(needle)}`);
  return result;
}

function q(value) {
  return JSON.stringify(String(value));
}

function toml({ schema = 1, squadName = 'Doctor Squad', memoryDir = '.muse/squad', providers, members }) {
  const lines = [`schema = ${schema}`, ''];
  for (const [name, provider] of Object.entries(providers)) {
    lines.push(`[providers.${name}]`, `type = ${q(provider.type)}`);
    if (provider.type === 'http') {
      lines.push(
        `base_url = ${q(provider.base_url)}`,
        `api_key = ${q(provider.api_key)}`,
        `model = ${q(provider.model)}`
      );
    } else {
      lines.push(`model = ${q(provider.model)}`);
    }
    lines.push(`max_concurrency = ${provider.max_concurrency || 1}`, '');
  }
  lines.push('[squad]', `name = ${q(squadName)}`, `memory_dir = ${q(memoryDir)}`, '');
  for (const [name, member] of Object.entries(members)) {
    lines.push(
      `[squad.${name}]`,
      `primary = ${q(member.primary)}`,
      `fallback = [${member.fallback.map((item) => q(item)).join(', ')}]`,
      `charter = """${member.charter}"""`,
      ''
    );
  }
  return lines.join('\n');
}

async function listen(server) {
  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', resolve);
  });
  return server.address().port;
}

function close(server) {
  return new Promise((resolve) => server.close(resolve));
}

async function main() {
  const requests = [];
  const server = http.createServer((request, response) => {
    requests.push({ url: request.url, method: request.method, auth: request.headers.authorization });
    const send = (status, body) => {
      response.writeHead(status, { 'content-type': 'application/json' });
      response.end(JSON.stringify(body));
    };
    const url = request.url;
    if (url === '/v1/models' || url === '/models') {
      send(200, { data: [{ id: 'good-model' }] });
    } else if (url === '/bad/v1/models') {
      send(500, { error: 'boom' });
    } else if (url === '/auth/v1/models') {
      send(401, { error: 'bad key' });
    } else if (url === '/slow/v1/models') {
      setTimeout(() => send(200, { data: [] }), 500);
    } else {
      send(404, { error: 'not found' });
    }
  });
  const port = await listen(server);
  const base = `http://127.0.0.1:${port}`;
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'muse-squad-doctor-'));

  try {
    const configDir = path.join(tempDir, 'config');
    const mcpDir = path.join(configDir, 'mcp');
    fs.mkdirSync(mcpDir, { recursive: true });
    const configFile = path.join(configDir, 'muse-squad.toml');
    const settingsFile = path.join(configDir, 'settings.json');
    const bridgeFile = path.join(mcpDir, 'bridge.js');
    fs.writeFileSync(bridgeFile, '// bridge stub\n');

    const native = {
      'Native-Core': { type: 'native', model: 'muse-spark-1.3-contributor', max_concurrency: 2 }
    };
    const goodHttp = {
      'Http-Good': { type: 'http', base_url: `${base}/v1`, api_key: SECRET, model: 'good-model' },
      'Http-Models': { type: 'http', base_url: `${base}/models`, api_key: SECRET, model: 'models-model' }
    };
    const goodConfig = {
      providers: { ...native, ...goodHttp },
      members: {
        atlas: { primary: 'Native-Core', fallback: ['Http-Good'], charter: 'Plan work. Verify with tests.' },
        runner: { primary: 'Http-Good', fallback: ['Native-Core'], charter: 'Implement changes. Report exact commands.' }
      }
    };

    const writeConfig = (config, file = configFile) => fs.writeFileSync(file, toml(config));
    const sync = (extra = []) => {
      const result = runSync(SYNC, ['--config-dir', configDir, ...extra]);
      assert(result.status === 0, `sync-team failed: ${result.stderr || result.stdout}`);
      return result.stdout;
    };
    const register = (file = configFile) => {
      const result = runSync(REGISTER, [
        '--settings', settingsFile, '--bridge', bridgeFile, '--config-file', file
      ]);
      assert(result.status === 0, `register-settings failed: ${result.stderr || result.stdout}`);
    };
    const mutateSettings = (mutator) => {
      const settings = JSON.parse(fs.readFileSync(settingsFile, 'utf8'));
      mutator(settings);
      fs.writeFileSync(settingsFile, JSON.stringify(settings, null, 2));
    };
    const args = ['--config-dir', configDir, '--timeout-ms', '1000'];

    writeConfig(goodConfig);
    register();
    sync();

    const help = runSync(DOCTOR, ['--help']);
    assert(help.status === 0, `--help exited ${help.status}`);
    expectContains(help.stdout, 'Usage: node doctor.js', '--help output');
    expectContains(help.stdout, '--timeout-ms', '--help output');
    expectContains(help.stdout, '--json', '--help output');

    const healthy = await expectDoctor(args, {
      contains: ['squad-doctor', 'Overall: all checks passed', 'settings.json', 'muse-squad.toml', 'no generic agents']
    });
    expectContains(healthy.stdout, 'NATIVE', 'native provider status');
    expectContains(healthy.stdout, 'not pinged', 'native provider is not pinged');
    expectContains(healthy.stdout, 'OK', 'http provider status');

    const envHealthy = await expectDoctor([], {
      env: { MUSE_CONFIG_DIR: configDir, MUSE_SQUAD_CONFIG_FILE: configFile },
      contains: ['Overall: all checks passed']
    });
    expectContains(envHealthy.stdout, 'squad-doctor', 'env-based run output');

    await expectDoctor(['--dir', configDir, '--timeout-ms', '1000'], {
      contains: ['Overall: all checks passed']
    });

    const jsonResult = await expectDoctor([...args, '--json']);
    const report = JSON.parse(jsonResult.stdout);
    assert(report.ok === true && report.problems === 0, 'JSON report is healthy');
    assert(
      JSON.stringify(Object.keys(report.checks).sort()) ===
        JSON.stringify(['config', 'providers', 'roster', 'settings']),
      'JSON report has the documented checks'
    );
    assert(report.checks.settings.status === 'OK', 'JSON settings check');
    assert(report.checks.config.status === 'OK', 'JSON config check');
    assert(report.checks.roster.status === 'OK', 'JSON roster check');
    assert(Array.isArray(report.checks.providers), 'JSON providers is an array');
    assert(report.checks.providers.length === 3, 'JSON report lists all providers');
    const goodStatuses = Object.fromEntries(
      report.checks.providers.map((provider) => [provider.provider, provider.status])
    );
    assert(goodStatuses['Native-Core'] === 'NATIVE', 'native status in JSON');
    assert(goodStatuses['Http-Good'] === 'OK', 'http status in JSON');
    assert(goodStatuses['Http-Models'] === 'OK', '/models URL status in JSON');
    assert(!jsonResult.stdout.includes(SECRET), 'JSON report redacts secrets');

    requests.length = 0;
    await expectDoctor([...args, '--json']);
    assert(requests.length === 2, `expected only the two HTTP providers to be pinged, saw ${requests.length}`);
    assert(requests.every((request) => request.method === 'GET'), 'providers are pinged with GET');
    assert(
      requests.every((request) => request.auth === `Bearer ${SECRET}`),
      'HTTP pings send the configured key'
    );
    const urls = requests.map((request) => request.url).sort();
    assert(JSON.stringify(urls) === JSON.stringify(['/models', '/v1/models']), 'both models URLs were used');

    // Provider statuses: AUTH / HTTP / TIMEOUT / DOWN, with no ping for native providers.
    const statusConfig = {
      providers: {
        'Native-Core': native['Native-Core'],
        'Http-Good': goodHttp['Http-Good'],
        'Http-Auth': { type: 'http', base_url: `${base}/auth`, api_key: SECRET, model: 'auth-model' },
        'Http-Bad': { type: 'http', base_url: `${base}/bad`, api_key: SECRET, model: 'bad-model' },
        'Http-Slow': { type: 'http', base_url: `${base}/slow`, api_key: SECRET, model: 'slow-model' },
        'Http-Down': { type: 'http', base_url: 'http://127.0.0.1:1/v1', api_key: SECRET, model: 'down-model' }
      },
      members: {
        atlas: { primary: 'Native-Core', fallback: ['Http-Good'], charter: 'Plan work. Verify with tests.' }
      }
    };
    writeConfig(statusConfig);
    sync();
    requests.length = 0;
    const statusResult = await expectDoctor(['--config-dir', configDir, '--timeout-ms', '100', '--json'], {
      status: 1
    });
    const statusReport = JSON.parse(statusResult.stdout);
    assert(statusReport.ok === false, 'unhealthy provider report');
    assert(statusReport.problems === 4, `expected four failing providers, got ${statusReport.problems}`);
    const statuses = Object.fromEntries(
      statusReport.checks.providers.map((provider) => [provider.provider, provider.status])
    );
    assert(statuses['Native-Core'] === 'NATIVE', 'native provider reported as NATIVE');
    assert(statuses['Http-Good'] === 'OK', 'healthy provider reported as OK');
    assert(statuses['Http-Auth'] === 'AUTH', '401 provider reported as AUTH');
    assert(statuses['Http-Bad'] === 'HTTP', '500 provider reported as HTTP');
    assert(statuses['Http-Slow'] === 'TIMEOUT', 'slow provider reported as TIMEOUT');
    assert(statuses['Http-Down'] === 'DOWN', 'unreachable provider reported as DOWN');
    // Four HTTP providers reach the mock server; Http-Down targets a closed port.
    // Native-Core has no URL at all, so it cannot appear in this list.
    assert(requests.length === 4, `native providers must not be pinged, saw ${requests.length} requests`);

    writeConfig(goodConfig);
    sync();

    // settings.json registration details.
    mutateSettings((settings) => { delete settings.mcpServers['muse-squad']; });
    await expectDoctor(args, {
      status: 1,
      contains: ['muse-squad is not registered under mcpServers', 'Overall: 1 problem found']
    });
    register();

    mutateSettings((settings) => { settings.mcpServers['muse-squad'].command = 'python'; });
    await expectDoctor(args, { status: 1, contains: ['command=python'] });
    register();

    mutateSettings((settings) => {
      settings.mcpServers['muse-squad'].args = [path.join(configDir, 'mcp', 'other.js')];
    });
    const badBridge = await expectDoctor([...args, '--json'], { status: 1 });
    const bridgeReport = JSON.parse(badBridge.stdout);
    assert(bridgeReport.checks.settings.status === 'BAD', 'wrong bridge arg is BAD');
    expectContains(bridgeReport.checks.settings.detail, 'bridge=(missing)', 'wrong bridge detail');
    register();

    mutateSettings((settings) => {
      settings.mcpServers['muse-squad'].env.MUSE_SQUAD_CONFIG_FILE = path.join(tempDir, 'env-mismatch.toml');
    });
    await expectDoctor(args, { status: 1, contains: ['env-mismatch.toml'] });
    register();

    mutateSettings((settings) => {
      settings.mcpServers['custom-coder'] = { command: 'node', args: ['legacy.js'] };
    });
    await expectDoctor(args, { status: 1, contains: ['legacy custom-coder still registered'] });
    register();

    mutateSettings((settings) => {
      settings.mcp_servers = { 'custom-coder': { command: 'node', args: ['legacy.js'] } };
    });
    await expectDoctor(args, { status: 1, contains: ['legacy custom-coder still registered'] });
    register();

    fs.writeFileSync(settingsFile, '{not json');
    await expectDoctor(args, { status: 1, contains: ['cannot parse'] });
    fs.unlinkSync(settingsFile);
    await expectDoctor(args, { status: 1, contains: ['settings.json not found'] });
    register();

    // Config validation.
    writeConfig({ ...goodConfig, schema: 2 });
    await expectDoctor(args, { status: 1, contains: ['schema must be 1'] });

    writeConfig({
      ...goodConfig,
      members: {
        atlas: { primary: 'Ghost-Provider', fallback: [], charter: 'Plan work. Verify with tests.' }
      }
    });
    await expectDoctor(args, { status: 1, contains: ['references unknown provider "Ghost-Provider"'] });

    writeConfig({ ...goodConfig, members: {} });
    await expectDoctor(args, { status: 1, contains: ['at least one squad member is required'] });

    fs.writeFileSync(configFile, 'schema = 1\n[squad.keaton\nprimary = "Native-Core"\n');
    await expectDoctor(args, { status: 1, contains: ['BAD'] });

    writeConfig(goodConfig);
    sync();

    // Roster / wrapper drift, stale wrappers, generic agents.
    const wrapper = path.join(configDir, 'agents', 'atlas.md');
    const originalWrapper = fs.readFileSync(wrapper, 'utf8');
    fs.writeFileSync(wrapper, `${originalWrapper}\n// drift\n`);
    await expectDoctor(args, { status: 1, contains: ['@atlas wrapper out of sync'] });
    sync();

    const roster = path.join(configDir, 'squad', 'team.md');
    const originalRoster = fs.readFileSync(roster, 'utf8');
    fs.writeFileSync(roster, `${originalRoster}\n// drift\n`);
    await expectDoctor(args, { status: 1, contains: ['squad/team.md out of sync'] });
    sync();

    fs.unlinkSync(path.join(configDir, 'agents', 'runner.md'));
    await expectDoctor(args, { status: 1, contains: ['@runner wrapper missing'] });
    sync();

    fs.unlinkSync(roster);
    await expectDoctor(args, { status: 1, contains: ['squad/team.md missing'] });
    sync();

    const stale = path.join(configDir, 'agents', 'ghost.md');
    fs.writeFileSync(stale, `${MARKER}\n# ghost\n`);
    await expectDoctor(args, { status: 1, contains: ['@ghost stale generated wrapper'] });
    fs.unlinkSync(stale);

    const human = path.join(configDir, 'agents', 'human.md');
    fs.writeFileSync(human, 'human-written agent\n');
    await expectDoctor(args, { contains: ['Overall: all checks passed'] });
    fs.unlinkSync(human);

    const genericFiles = ['worker.md', 'plan-reviewer.md', 'general-purpose.md']
      .map((name) => path.join(configDir, 'agents', name));
    for (const file of genericFiles) fs.writeFileSync(file, 'generic agent\n');
    const genericResult = await expectDoctor(args, {
      status: 1,
      contains: genericFiles.map((file) => `generic agent ${path.basename(file)} still present`),
      absent: ['no generic agents']
    });
    expectContains(genericResult.stdout, '1 problem found', 'roster check counts as one problem');
    for (const file of genericFiles) fs.unlinkSync(file);

    // Explicit config file takes precedence over the default filename.
    const altConfig = path.join(configDir, 'custom-squad.toml');
    writeConfig(goodConfig, altConfig);
    sync(['--file', altConfig]);
    register(altConfig);
    const fileResult = await expectDoctor(['--config-dir', configDir, '--file', altConfig, '--timeout-ms', '1000'], {
      contains: ['Overall: all checks passed']
    });
    expectContains(fileResult.stdout, 'custom-squad.toml', 'explicit config file is used');
    register();
    sync();

    await expectDoctor(args, { contains: ['Overall: all checks passed'] });

    for (const badArgs of [['--bogus'], ['--timeout-ms', '0'], ['--timeout-ms', 'abc'], ['--config-dir']]) {
      const result = runSync(DOCTOR, badArgs);
      assert(result.status === 2, `doctor exited ${result.status} for ${badArgs.join(' ')} (expected 2)`);
      assert(!`${result.stdout}${result.stderr}`.includes(SECRET), 'CLI errors must not leak secrets');
    }

    console.log('DOCTOR TESTS PASSED');
  } finally {
    fs.rmSync(tempDir, { recursive: true, force: true });
    await close(server);
  }
}

main().catch((error) => {
  process.stderr.write(`${error.stack || error.message}\n`);
  process.exitCode = 1;
});
